    public static void testArbBandNumbersAndTiesAreHeld() {
        emon.Testport.assertEq(Oarb.oaBandWord(1, 4, 1, 0), 0, "numbers held even with unanimous agreement");
        emon.Testport.assertEq(Oarb.oaBandWord(0, 2, 1, 0), 1, "dictionary word agreed by two views");
        emon.Testport.assertEq(Oarb.oaBandWord(0, 3, 0, 0), 1, "three views agree on a lexical form");
        emon.Testport.assertEq(Oarb.oaBandWord(0, 3, 1, 1), 0, "tie blocks");
        emon.Testport.assertEq(Oarb.oaBandRule(2, 0, 900), 0, "at least three accepted words");
        emon.Testport.assertEq(Oarb.oaBandRule(5, 1, 900), 0, "one unagreed lexical word blocks the band");
        emon.Testport.assertEq(Oarb.oaBandRule(5, 0, 599), 0, "at least sixty percent coverage");
        emon.Testport.assertEq(Oarb.oaBandRule(5, 0, 600), 1, "coverage boundary");
    }
    public static void testArbViewBudgetAndIntegerFactor() {
        emon.Testport.assertEq(Oarb.oaViewFactor(7, 36), 5, "seven pixel text gets integer x5");
        emon.Testport.assertEq(Oarb.oaViewFactor(1, 36), 6, "upscale cap");
        emon.Testport.assertEq(Oarb.oaViewFactor(40, 36), 1, "no downscale");
        emon.Testport.assertEq(Oarb.oaViewAllowed(0, 0, 0), 0, "born digital cannot request arbitration");
        emon.Testport.assertEq(Oarb.oaViewAllowed(1, 0, 3), 1, "last table view");
        emon.Testport.assertEq(Oarb.oaViewAllowed(1, 0, 4), 0, "two tables times two views");
        emon.Testport.assertEq(Oarb.oaViewAllowed(1, 1, 11), 1, "last band view");
        emon.Testport.assertEq(Oarb.oaViewAllowed(1, 1, 12), 0, "three bands times four views");
        emon.Testport.assertEq(Oarb.oaActive(), 0, "bulk arbitration stays off; the separate percent sign path is bounded in oapct");
    }
