    public static void testArbEqualMinimaBlockAndDuplicateReadingsDoNotVote() {
        emon.Port.Cells text = emon.Port.newCells();
        int bad = oatText3(text);
        int bad2 = oatText56(text);
        int total = oatText2(text);
        int a = oatText0(text);
        int b = oatText1(text);
        int c = oatText54(text);
        int d = oatText55(text);
        emon.Port.Cells inc = emon.Port.newCells();
        emon.Port.Cells candidates = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Oarbctx.OaWork work = new emon.Oarbctx.OaWork();
        oatInc(inc, bad, 2);
        oatInc(inc, bad2, 3);
        oatInc(inc, total, 3);
        oatCandidate(candidates, 0, a, 2);
        oatCandidate(candidates, 0, a, 2);
        oatCandidate(candidates, 1, b, 3);
        emon.Testport.assertEq(Oarb.oaBlock(text, inc, candidates, 0, 2, 2, out, work), 1, "duplicate readings are one possible assignment");
        oatCandidate(candidates, 0, c, 2);
        oatCandidate(candidates, 1, d, 3);
        emon.Testport.assertEq(Oarb.oaBlock(text, inc, candidates, 0, 2, 2, out, work), -2, "97+144 and 87+154 tie; agreement cannot decide");
    }
